message.content:
{
  "gate_token": "ifvTN128i41WL_TYSpERuA",
  "title": "The Mirror Road Through the Ruined City",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara unrolls a map of the ruined capital at dusk.",
      "visual_description": "A windswept hill overlooking a shattered skyline of broken spires; a battered map weighed down by a brass compass glints in the last sunlight.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The oracle lamp warns of three traps ahead.",
      "visual_description": "A small oil lamp held aloft, its single eye-flame casting forked shadows across Mara's ink-stained sleeve.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "The tin fox scouts the cracked outer gate.",
      "visual_description": "A clockwork fox crouched on a heap of rubble before enormous splintered castle gates, its blue glass eyes reflecting torchlight.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 4,
      "caption": "Glass Diver slips through a tall stained window.",
      "visual_description": "A figure in a clear diving helmet emerging headfirst from a colored windowpane as if from water, coat shimmering with broken reflections.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 5,
      "caption": "The team regroups in a courtyard of fallen banners.",
      "visual_description": "Torn royal banners pooled like red water across cobblestones; Mara, the lamp, and the fox huddle beside a dry fountain.",
      "characters": ["mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 6,
      "caption": "Frightened faces peer from boarded windows.",
      "visual_description": "Narrow alley lined with shuttered houses, pale eyes glinting between slats as Mara passes with the lamp raised.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 7,
      "caption": "An armored patrol marches past, missing them by inches.",
      "visual_description": "Rows of polished greaves and pike-shafts striding through a fog-thick street while the tin fox flattens behind a barrel.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 8,
      "caption": "The cursed tower hums with a beckoning light.",
      "visруall_description": "A leaning black tower wreathed in green light; Mara shields her eyes while the lamp whispers a warning.",
      "visual_description": "A leaning black tower wreathed in sickly green glow; Mara shields her eyes while the lamp's flame leans away, whispering.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 9,
      "caption": "The sleeping tax collector blocks a narrow stair.",
      "visual_description": "A plump official slumped on a stone step, ledger book under his cheek, stamped papers fluttering from his sleeves.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 10,
      "caption": "Mara tiptoes over him while the fox steals a key.",
      "visual_description": "The tin fox lifting an iron key ring in its jaws as Mara steps high over the snoring official.",
      "characters": ["mara_the_cartographer", "tin_fox", "sleeping_tax_collector"]
    },
    {
      "scene_number": 11,
      "caption": "Rumor of a great winged beast rattles the rooftops.",
      "visual_description": "Shingles vibrating, a long shadow sweeping across moonlit tile rooftops as the lamp's eye narrows to a slit.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 12,
      "caption": "Glass Diver dives through a mirrored ballroom wall.",
      "visual_description": "A grand ruined ballroom; the diver plunging into a tall mirror, ripples spreading across the silver surface.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 13,
      "caption": "Behind the mirror waits a sealed magic door.",
      "visual_description": "An archway carved with shifting runes glowing blue; the diver pressing a gloved palm to its center.",
      "characters": ["glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 14,
      "caption": "The lamp reads the door's true name aloud.",
      "visual_description": "Glyphs lifting off the door like embers and circling the oil lamp's flame as Mara watches in awe.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 15,
      "caption": "Inside, they find the lost charge in a glass coffin of light.",
      "visual_description": "A small luminous chamber where a sleeping figure rests inside a column of pale light; the tin fox circles protectively.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 16,
      "caption": "Alarms shriek; armored patrols converge on the keep.",
      "visual_description": "Red lanterns flaring along distant battlements; Mara hoisting the rescued figure as the fox bolts ahead down a corridor.",
      "characters": ["mara_the_cartographer", "tin_fox", "glass_diver"]
    },
    {
      "scene_number": 17,
      "caption": "They race onto the long bridge over the black river.",
      "visual_description": "A narrow stone bridge arching over churning dark water; sparks of torchlight chase the team across, the lamp blazing bright.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 18,
      "caption": "On the far bank, Mara marks the city closed on her map.",
      "visual_description": "Dawn rising behind the receding ruins; Mara draws an inked X over the city while the fox curls at her boots and the lamp dims to a contented spark.",
      "characters": ["mara_the_cartographer", "tin_fox", "oracle_lamp", "glass_diver"]
    }
  ]
}

